class.description:
A tree owns one [MultiplayerAPI] and installs it on its own branch of the [SceneTree], so every descendant returns [member Node.multiplayer] with that session and two trees in one [SceneTree] are two independent sessions. [codeblock] tree.peer_class = &"ENetMultiplayerPeer" tree.transport_settings = { port = 21253 }
# A peer the game already holds. var peer := ENetMultiplayerPeer.new() peer.create_client("127.0.0.1", 21253) tree.api.session_prepare_join(&"PlayerOne", []) tree.api.multiplayer_peer = peer
# Or one the provider knows how to build, prepared and assigned inside # the window the offer arrives in. Netw.connection(tree).create_peer( tree.peer_class, NetwMultiplayer.TRANSPORT_MODE_CLIENT, "127.0.0.1:21253", tree.transport_settings, func(peer: MultiplayerPeer, error: Error, _detail: String) -> void: if error == OK: tree.api.session_prepare_join(&"PlayerOne", []) tree.api.multiplayer_peer = peer, ) [/codeblock]
